from lib import *
S = SS('p43')
steps = [
    step("sitemap 索引的根元素是 {http://www.sitemaps.org/schemas/sitemap/0.9}sitemapindex——带命名空间。用 findall(\"sitemap/loc\") 不写命名空间找到 0 个;写上命名空间 {ns}sitemap/{ns}loc 才找到 3 个;用 lxml 的 xpath(\"//*[local-name()='loc']/text()\") 不依赖命名空间也找到 3 个。这是解析 sitemap 最常见的“明明有数据却解析出 0 条”。", t=tl(S(1)), done=lidx(S(1), '写上命名空间', 'local-name'), mark=lidx(S(1), '不写命名空间'), b=bars([['不写命名空间:找到', 0, '0'], ['写上命名空间:找到', 3, '3'], ['local-name():找到', 3, '3']], 3, mark=[0], done=[1, 2]), kv=KV([['不写命名空间', '0 个'], ['写命名空间', '3 个'], ['xpath local-name()', '3 个,与命名空间无关']], ['不写命名空间'])),
    step("gzip 有两种形式。/sitemap2.xml.gz 是文件本身压缩(Content-Type: application/gzip,没有 Content-Encoding):requests 给出的 r.content 开头字节是 1f8b,仍是 gzip,要自己 gzip.decompress,解压后能解析 5 个 URL;不解压直接 ET.fromstring 报 ParseError(not well-formed)。/sitemap3.xml 是 HTTP 层 Content-Encoding: gzip:r.content 开头是 3c3f(\"<?\"),requests 已经替你解开了,明文 XML。两者都要处理。", t=tl(S(2)), done=lidx(S(2), '/sitemap3.xml', 'gzip.decompress'), mark=lidx(S(2), '/sitemap2.xml.gz:', '不解压直接'), kv=KV([['.xml.gz 文件', 'r.content 仍是 gzip(1f8b)'], ['Content-Encoding: gzip', 'requests 已解开(3c3f)'], ['不解压就解析', 'ParseError']], ['.xml.gz 文件'])),
    step("lastmod 有多种写法:2026-10-11 → 2026-10-11 00:00:00+00:00;带时区的 2026-10-11T08:30:00+08:00 和 …Z 都能被 datetime.fromisoformat 解析;带空格的 2026-10-11 08:30 也能解析(没有时区,我补了 UTC);11/10/2026、RFC 2822 的 Sun, 11 Oct 2026 00:30:00 GMT、空串都解析不了(None)。3 个子 sitemap 共 15 条 URL,上次抓取时间 2026-10-05:lastmod 更新的 5 条,没有 lastmod 的 5 条(无法判断是否更新,只能当作需要抓)。", t=tl(S(3)), done=lidx(S(3), '2026-10-11T08:30:00+08:00', 'T00:30:00Z', '共 15 条 URL'), mark=lidx(S(3), '11/10/2026', 'Sun, 11 Oct', "''"), kv=KV([['能解析', '日期、带时区的日期时间、…Z'], ['解析不了', '11/10/2026、RFC 2822 日期、空'], ['没有 lastmod', '5 条,只能当作需要抓']], ['没有 lastmod'])),
    step("5 万条 URL 的 sitemap(6.8 MiB 未压缩,gzip 后 0.26 MiB):ElementTree.fromstring 一次性解析 312 ms,内存峰值 38.5 MiB;iterparse 边读边 clear 389 ms,内存峰值 4.0 MiB。流式解析慢一点,但内存只要九分之一左右。", t=tl(S(4)), done=lidx(S(4), 'iterparse'), mark=lidx(S(4), 'fromstring'), b=bars([['fromstring 内存峰值 MiB', 38.5, '38.5'], ['iterparse 内存峰值 MiB', 4.0, '4.0'], ['fromstring 耗时 ms', 312, '312'], ['iterparse 耗时 ms', 389, '389']], 400, mark=[0], done=[1]), kv=KV([['fromstring', '312 ms,内存 38.5 MiB'], ['iterparse + clear', '389 ms,内存 4.0 MiB'], ['文件', '6.8 MiB(gzip 后 0.26 MiB)']], ['iterparse + clear'])),
    step("脏数据:URL 里 & 没有转义成 &amp;,标准库 ElementTree 直接报 ParseError。lxml 的 recover=True 能读出 4 条,但内容被悄悄破坏了:未转义的 http://shop.test/a?x=1&y=2 读成了 http://shop.test/a?x=1=2(丢了 \"&y\"),连旁边写得正确的 …?x=1&amp;y=2 也变成了 …?x=1y=2(丢了 &)。读出来还有跨主机的 http://other.test/zzz 和相对路径 /relative/path,各自需要单独处理。恢复模式拿到的 URL 要验证,不能直接抓。", t=tl(S(5)), done=lidx(S(5), 'recover=True 能读出 4 条'), mark=lidx(S(5), '未转义的 &', '跨主机', '相对路径'), kv=KV([['标准库 ElementTree', '遇到未转义的 & 报错'], ['lxml recover=True', '读出 4 条,但 x=1&y=2 被破坏'], ['其它脏数据', '跨主机 URL、相对路径']], ['lxml recover=True'])),
]
A = mkartp('p43', 43, '爬虫,sitemap,sitemap.xml,gzip,lastmod,iterparse,lxml,XML命名空间,Python,真实验证,动画演示',
    '实测 sitemap.xml 解析:不写 XML 命名空间会解析出 0 条;.xml.gz 文件要自己解压而 Content-Encoding: gzip 由 requests 解开;lastmod 有多种写法,没有 lastmod 的条目不能用来增量;5 万条 URL 用 iterparse 内存 4.0 MiB 对 fromstring 38.5 MiB;lxml 恢复模式会悄悄破坏含 & 的 URL。',
    'sitemap.xml 是爬虫最省力的 URL 来源,但解析它的坑不少:命名空间、两种 gzip、五花八门的 lastmod、几万条 URL 的内存、以及不规范的 XML。这篇用一个本机服务器把这些情形逐一复现。',
    [('0 个', '不写 XML 命名空间时,findall("sitemap/loc") 找到的 URL 数(写对是 3 个)'), ('38.5 对 4.0 MiB', '5 万条 URL 的 sitemap,fromstring 与 iterparse 的内存峰值'), ('x=1y=2', 'lxml recover=True 把正确转义的 x=1&amp;y=2 读成的样子')],
    [('命名空间', '<p>sitemap 的所有元素都在 <code>http://www.sitemaps.org/schemas/sitemap/0.9</code> 命名空间里。<code>findall("sitemap/loc")</code> 找不到任何东西,必须写 <code>{ns}sitemap/{ns}loc</code>,或者用 xpath 的 <code>local-name()</code> 绕过。</p>'),
     ('两种 gzip', '<p><code>.xml.gz</code> 是文件本身压缩,requests 不会替你解压;<code>Content-Encoding: gzip</code> 是 HTTP 层压缩,requests 自动解开。判断依据是内容的开头字节(<code>1f 8b</code> 表示仍是 gzip),不是文件扩展名。</p>'),
     ('lastmod', '<p><code>datetime.fromisoformat</code> 能解析日期、带时区的时间和 <code>Z</code> 结尾的时间;<code>11/10/2026</code> 或 RFC 2822 日期解析不了。没有 <code>lastmod</code> 的条目(例子里 5/15)不能用来判断是否更新,增量抓取要把它们当作“需要抓”。</p>'),
     ('大 sitemap', '<p>5 万条 URL 的 6.8 MiB sitemap,<code>fromstring</code> 内存峰值 38.5 MiB,<code>iterparse</code> 边读边 <code>clear</code> 只要 4.0 MiB(多花 77 ms)。协议允许的上限我没有在这里核对(我印象里是 5 万条或 50 MB,以官方文档为准)。</p>'),
     ('脏数据', '<p>XML 里 <code>&</code> 没转义是常见错误。标准库直接报错;lxml 的 <code>recover=True</code> 能读,但把 <code>x=1&y=2</code> 读成 <code>x=1=2</code>,甚至把旁边写对了的 <code>x=1&amp;y=2</code> 读成 <code>x=1y=2</code>。另外 sitemap 里可能有跨主机的 URL 和相对路径,要按所在站点校验后再抓。</p>')],
    steps,
    [ENV_P + '。服务器提供 sitemap 索引、普通 sitemap、.xml.gz、以及带 Content-Encoding: gzip 的 sitemap;解析用标准库 xml.etree.ElementTree 与 lxml 6.1.1;大 sitemap 是合成的 50000 条 URL(6.8 MiB);内存用 tracemalloc 峰值;脏数据是手写的一小段 XML',
     '没有验证:sitemap 协议规定的数量与大小上限(只凭印象);sitemap 里的 image、video、news 扩展命名空间;robots.txt 里的 Sitemap 行与 sitemap 的主机一致性检查;很大的 sitemap 索引(几千个子文件)的并发下载;lxml 恢复模式在其它 libxml2 版本里的表现;defusedxml 等防御 XML 实体炸弹的库(没有安装,也没有测 billion laughs 攻击)'],
    'sitemap.xml 解析')
